'use client';
import React, { useState, useEffect, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { useMsal } from '@azure/msal-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { MultiSelect } from '@/components/ui/multi-select';
import {
    ArrowLeft, Download, RefreshCw, Edit2, RotateCcw,
    Search, Shield, ShieldCheck, Users, FileSpreadsheet, CheckCircle2,
    Filter, X, Layers, ChevronDown, ChevronUp, CirclePlus, Sparkles,
} from 'lucide-react';
import {
    ASSIGNMENTS_FILTERS_ENDPOINT,
    GROUPS_LIST_ENDPOINT,
    ROLE_SCOPETAGS_ENDPOINT,
    MIGRATION_BUILDER_SESSION_KEY,
} from '@/lib/constants';
import { useApiRequest } from '@/hooks/useApiRequest';
import { AssignmentFilter } from '@/types/assignmentFilter';

// ─── Types ───────────────────────────────────────────────────────────────────

interface SourceAssignment extends Record<string, unknown> {
    resourceType: string;
    subResourceType: string;
    assignmentType: string;
    platform: string | null;
    isAssigned: boolean;
    targetId: string | null;
    targetName: string;
    resourceId: string;
    resourceName: string | null;
    filterId: string | null;
    filterType: string;
    assignmentDirection: string;
    isExcluded: boolean;
    scopeTagIds?: string[];
}

interface GroupItem {
    id: string;
    displayName: string;
    description: string | null;
    membershipRule: string | null;
}

interface RoleScopeTag {
    id: string;
    displayName: string;
    isBuildIn: boolean;
}

type AssignmentAction = 'Add' | 'Remove' | 'NoAssignment' | 'Replace';
type FilterType = 'Include' | 'Exclude' | 'None';

interface EditableFields {
    groupName: string;
    groupId: string | null;
    assignmentAction: AssignmentAction;
    filterName: string | null;
    filterId: string | null;
    filterType: FilterType;
    scopeTagIds: string[];
}

interface BuilderRow extends EditableFields {
    id: string;
    policyName: string;
    resourceType: string;
    assignmentDirection: string;
    original: EditableFields;
    isModified: boolean;
    isGenerated?: boolean;   // true = created by a ring template
    ringLabel?: string;      // e.g. "Ring 1 – Include"
}

// One side (Include or Exclude) of a ring template
interface RingSlot {
    enabled: boolean;
    groupName: string;
    groupId: string | null;
    assignmentAction: AssignmentAction;
    filterId: string | null;
    filterName: string | null;
    filterType: FilterType;
    scopeTagIds: string[];
}

// Simple bulk override (non-ring mode)
interface BulkTemplate {
    groupName: string;
    groupId: string | null;
    assignmentAction: AssignmentAction | '__keep__';
    filterId: string | null;
    filterName: string | null;
    filterType: FilterType;
    scopeTagIds: string[];
}

// ─── Constants ────────────────────────────────────────────────────────────────

const SPECIAL_TARGETS = ['All Users', 'All Devices'];

const EMPTY_RING_SLOT: RingSlot = {
    enabled: true,
    groupName: '', groupId: null,
    assignmentAction: 'Add',
    filterId: null, filterName: null, filterType: 'None',
    scopeTagIds: [],
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function normalizeFilterType(ft: string): FilterType {
    if (!ft || ft === 'None') return 'None';
    const l = ft.toLowerCase();
    if (l === 'include') return 'Include';
    if (l === 'exclude') return 'Exclude';
    return 'None';
}

function toBuilderRows(assignments: SourceAssignment[]): BuilderRow[] {
    return assignments.map((a, i) => {
        const filterType = normalizeFilterType(a.filterType);
        const base: EditableFields = {
            groupName: a.targetName || '',
            groupId: a.targetId || null,
            assignmentAction: a.targetName ? 'Add' : 'NoAssignment',
            filterName: null,
            filterId: a.filterId && a.filterId !== 'None' ? a.filterId : null,
            filterType,
            scopeTagIds: a.scopeTagIds || [],
        };
        return {
            id: `row-${i}-${Date.now()}`,
            policyName: a.resourceName || '',
            resourceType: a.resourceType,
            assignmentDirection: a.assignmentDirection || 'Include',
            ...base,
            original: { ...base },
            isModified: false,
        };
    });
}

function rowIsModified(row: BuilderRow, next: Partial<EditableFields>): boolean {
    const merged = { ...row, ...next };
    return (
        merged.groupName !== row.original.groupName ||
        merged.assignmentAction !== row.original.assignmentAction ||
        merged.filterId !== row.original.filterId ||
        merged.filterType !== row.original.filterType ||
        JSON.stringify([...merged.scopeTagIds].sort()) !== JSON.stringify([...row.original.scopeTagIds].sort())
    );
}

// ─── Page Component ───────────────────────────────────────────────────────────

export default function MigrationBuilderPage() {
    const router = useRouter();
    const { accounts } = useMsal();
    const { request } = useApiRequest();

    // Reference data
    const [rows, setRows] = useState<BuilderRow[]>([]);
    const [groups, setGroups] = useState<GroupItem[]>([]);
    const [filters, setFilters] = useState<AssignmentFilter[]>([]);
    const [scopeTags, setScopeTags] = useState<RoleScopeTag[]>([]);
    const [loading, setLoading] = useState(false);
    const [dataLoaded, setDataLoaded] = useState(false);

    // Filter panel
    const [filterPanelOpen, setFilterPanelOpen] = useState(false);
    const [scopeTagFilter, setScopeTagFilter] = useState<string[]>([]);
    const [resourceTypeFilter, setResourceTypeFilter] = useState<string[]>([]);
    const [actionFilter, setActionFilter] = useState<string[]>([]);
    const [policySearch, setPolicySearch] = useState('');

    // Row selection
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

    // ── Bulk / Ring template dialog ───────────────────────────────────────────
    const [templateDialogOpen, setTemplateDialogOpen] = useState(false);
    const [ringMode, setRingMode] = useState(false);

    // Ring template state
    const [ringName, setRingName] = useState('Ring 1');
    const [ringInclude, setRingInclude] = useState<RingSlot>({ ...EMPTY_RING_SLOT });
    const [ringExclude, setRingExclude] = useState<RingSlot>({ ...EMPTY_RING_SLOT });
    const [ringIncludeGroupSearch, setRingIncludeGroupSearch] = useState('');
    const [ringExcludeGroupSearch, setRingExcludeGroupSearch] = useState('');
    const [ringIncludeFilterSearch, setRingIncludeFilterSearch] = useState('');
    const [ringExcludeFilterSearch, setRingExcludeFilterSearch] = useState('');

    // Simple bulk template state
    const [bulk, setBulk] = useState<BulkTemplate>({
        groupName: '', groupId: null, assignmentAction: '__keep__',
        filterId: null, filterName: null, filterType: 'None', scopeTagIds: [],
    });
    const [bulkGroupSearch, setBulkGroupSearch] = useState('');
    const [bulkFilterSearch, setBulkFilterSearch] = useState('');

    // Single-row edit dialog
    const [editingRow, setEditingRow] = useState<BuilderRow | null>(null);
    const [editDialogOpen, setEditDialogOpen] = useState(false);
    const [groupSearch, setGroupSearch] = useState('');
    const [filterSearch, setFilterSearch] = useState('');

    // ── Load from sessionStorage ──────────────────────────────────────────────
    useEffect(() => {
        const stored = sessionStorage.getItem(MIGRATION_BUILDER_SESSION_KEY);
        if (stored) {
            try {
                const assignments: SourceAssignment[] = JSON.parse(stored);
                setRows(toBuilderRows(assignments));
            } catch (e) {
                console.error('Failed to parse stored assignments', e);
            }
        }
    }, []);

    // Resolve filter names once filters are loaded
    useEffect(() => {
        if (!filters.length || !rows.length) return;
        setRows(prev => prev.map(row => {
            if (!row.filterId) return row;
            const filter = filters.find(f => f.id === row.filterId);
            if (!filter || filter.displayName === row.filterName) return row;
            return { ...row, filterName: filter.displayName, original: { ...row.original, filterName: filter.displayName } };
        }));
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [filters]);

    // ── Fetch reference data ──────────────────────────────────────────────────
    const fetchReferenceData = async () => {
        if (!accounts.length) return;
        setLoading(true);
        try {
            const [groupRes, filterRes, tagRes] = await Promise.all([
                request<{ data: GroupItem[] }>(GROUPS_LIST_ENDPOINT, { method: 'GET' }),
                request<{ data: AssignmentFilter[] }>(ASSIGNMENTS_FILTERS_ENDPOINT, { method: 'GET' }),
                request<{ data: RoleScopeTag[] }>(ROLE_SCOPETAGS_ENDPOINT, { method: 'GET' }),
            ]);
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const asArray = <T,>(res: any): T[] => {
                const inner = res?.data?.data;
                return Array.isArray(inner) ? (inner as T[]) : [];
            };
            setGroups(asArray<GroupItem>(groupRes));
            setFilters(asArray<AssignmentFilter>(filterRes));
            setScopeTags(asArray<RoleScopeTag>(tagRes));
            setDataLoaded(true);
        } finally {
            setLoading(false);
        }
    };

    // ── Memos ─────────────────────────────────────────────────────────────────
    const scopeTagOptions = useMemo(() => scopeTags.map(t => ({ label: t.displayName, value: t.id })), [scopeTags]);
    const resourceTypeOptions = useMemo(() => {
        const types = [...new Set(rows.map(r => r.resourceType))].filter(Boolean).sort();
        return types.map(t => ({ label: t, value: t }));
    }, [rows]);
    const actionOptions = [
        { label: 'Add', value: 'Add' }, { label: 'Remove', value: 'Remove' },
        { label: 'Replace', value: 'Replace' }, { label: 'NoAssignment', value: 'NoAssignment' },
    ];

    const displayedRows = useMemo(() => {
        let result = rows;
        if (policySearch.trim()) {
            const q = policySearch.toLowerCase();
            result = result.filter(r => r.policyName.toLowerCase().includes(q) || r.groupName.toLowerCase().includes(q));
        }
        if (scopeTagFilter.length > 0)
            result = result.filter(r => scopeTagFilter.some(id => r.scopeTagIds.includes(id)));
        if (resourceTypeFilter.length > 0)
            result = result.filter(r => resourceTypeFilter.includes(r.resourceType));
        if (actionFilter.length > 0)
            result = result.filter(r => actionFilter.includes(r.assignmentAction));
        return result;
    }, [rows, policySearch, scopeTagFilter, resourceTypeFilter, actionFilter]);

    const activeFilterCount = scopeTagFilter.length + resourceTypeFilter.length + actionFilter.length + (policySearch.trim() ? 1 : 0);

    // Group/filter search lists for all pickers
    const mkGroupList = (q: string) => {
        const lq = q.toLowerCase().trim();
        if (!lq) return groups.slice(0, 60);
        return groups.filter(g => g.displayName.toLowerCase().includes(lq)).slice(0, 60);
    };
    const mkFilterList = (q: string) => {
        const lq = q.toLowerCase().trim();
        if (!lq) return filters.slice(0, 60);
        return filters.filter(f => f.displayName.toLowerCase().includes(lq)).slice(0, 60);
    };

    const modifiedCount = rows.filter(r => r.isModified).length;
    const generatedCount = rows.filter(r => r.isGenerated).length;
    const allDisplayedSelected = displayedRows.length > 0 && displayedRows.every(r => selectedIds.has(r.id));
    const someDisplayedSelected = displayedRows.some(r => selectedIds.has(r.id));

    // ── Selection ─────────────────────────────────────────────────────────────
    const toggleRow = (id: string) => {
        setSelectedIds(prev => {
            const next = new Set(prev);
            if (next.has(id)) { next.delete(id); } else { next.add(id); }
            return next;
        });
    };
    const toggleAll = () => {
        if (allDisplayedSelected) {
            setSelectedIds(prev => { const n = new Set(prev); displayedRows.forEach(r => n.delete(r.id)); return n; });
        } else {
            setSelectedIds(prev => { const n = new Set(prev); displayedRows.forEach(r => n.add(r.id)); return n; });
        }
    };
    const clearSelection = () => setSelectedIds(new Set());

    // ── Open template dialog ──────────────────────────────────────────────────
    const openTemplateDialog = () => {
        setBulkGroupSearch(''); setBulkFilterSearch('');
        setRingIncludeGroupSearch(''); setRingExcludeGroupSearch('');
        setRingIncludeFilterSearch(''); setRingExcludeFilterSearch('');
        setTemplateDialogOpen(true);
    };

    // ── Single-row edit ───────────────────────────────────────────────────────
    const openEdit = (row: BuilderRow) => {
        setEditingRow({ ...row });
        setGroupSearch(''); setFilterSearch('');
        setEditDialogOpen(true);
    };
    const saveEdit = () => {
        if (!editingRow) return;
        setRows(prev => prev.map(r => r.id !== editingRow.id ? r : { ...editingRow, isModified: rowIsModified(r, editingRow) }));
        setEditDialogOpen(false);
        setEditingRow(null);
    };
    const resetRow = (rowId: string) => {
        setRows(prev => prev.map(r => r.id !== rowId ? r : { ...r, ...r.original, isModified: false }));
    };
    const deleteRow = (rowId: string) => {
        setRows(prev => prev.filter(r => r.id !== rowId));
        setSelectedIds(prev => { const n = new Set(prev); n.delete(rowId); return n; });
    };

    // ── Bulk apply (non-ring) ─────────────────────────────────────────────────
    const applyBulkTemplate = () => {
        setRows(prev => prev.map(r => {
            if (!selectedIds.has(r.id)) return r;
            const patch: Partial<EditableFields> = {};
            if (bulk.groupName) { patch.groupName = bulk.groupName; patch.groupId = bulk.groupId; }
            if (bulk.assignmentAction && bulk.assignmentAction !== '__keep__') patch.assignmentAction = bulk.assignmentAction as AssignmentAction;
            if (bulk.filterId !== null) { patch.filterId = bulk.filterId; patch.filterName = bulk.filterName; patch.filterType = bulk.filterType; }
            if (bulk.scopeTagIds.length > 0) patch.scopeTagIds = bulk.scopeTagIds;
            const merged = { ...r, ...patch };
            return { ...merged, isModified: rowIsModified(r, patch) };
        }));
        clearSelection();
        setTemplateDialogOpen(false);
        setBulk({ groupName: '', groupId: null, assignmentAction: '__keep__', filterId: null, filterName: null, filterType: 'None', scopeTagIds: [] });
    };

    // ── Ring template apply ───────────────────────────────────────────────────
    // For each selected policy, generate an Include row and/or Exclude row and ADD them to the table.
    // The original selected rows are kept as-is (they represent the existing state).
    const applyRingTemplate = () => {
        const selectedRows = rows.filter(r => selectedIds.has(r.id));
        // Deduplicate by policyName so we don't generate duplicate ring rows for the same policy
        const seen = new Set<string>();
        const newRows: BuilderRow[] = [];

        for (const r of selectedRows) {
            const key = r.policyName;
            if (seen.has(key)) continue;
            seen.add(key);

            if (ringInclude.enabled && ringInclude.groupName) {
                const base: EditableFields = {
                    groupName: ringInclude.groupName, groupId: ringInclude.groupId,
                    assignmentAction: ringInclude.assignmentAction,
                    filterId: ringInclude.filterId, filterName: ringInclude.filterName,
                    filterType: ringInclude.filterType, scopeTagIds: ringInclude.scopeTagIds,
                };
                newRows.push({
                    id: `ring-inc-${r.policyName}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
                    policyName: r.policyName,
                    resourceType: r.resourceType,
                    assignmentDirection: 'Include',
                    ...base,
                    original: { ...base },
                    isModified: false,
                    isGenerated: true,
                    ringLabel: `${ringName} – Include`,
                });
            }

            if (ringExclude.enabled && ringExclude.groupName) {
                const base: EditableFields = {
                    groupName: ringExclude.groupName, groupId: ringExclude.groupId,
                    assignmentAction: ringExclude.assignmentAction,
                    filterId: ringExclude.filterId, filterName: ringExclude.filterName,
                    filterType: ringExclude.filterType, scopeTagIds: ringExclude.scopeTagIds,
                };
                newRows.push({
                    id: `ring-exc-${r.policyName}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
                    policyName: r.policyName,
                    resourceType: r.resourceType,
                    assignmentDirection: 'Exclude',
                    ...base,
                    original: { ...base },
                    isModified: false,
                    isGenerated: true,
                    ringLabel: `${ringName} – Exclude`,
                });
            }
        }

        setRows(prev => [...prev, ...newRows]);
        clearSelection();
        setTemplateDialogOpen(false);
    };

    // ── Export ────────────────────────────────────────────────────────────────
    const exportCSV = () => {
        const resolveTagNames = (ids: string[]) =>
            ids.map(id => scopeTags.find(t => t.id === id)?.displayName || id).join(', ') || 'None';
        const header = 'PolicyName;GroupName;AssignmentDirection;AssignmentAction;Filter;Filter Type;Role Scope Tags';
        const csvRows = rows.map(r => [
            r.policyName, r.groupName, r.assignmentDirection, r.assignmentAction,
            r.filterName || '',
            r.filterType === 'None' ? '' : r.filterType,
            resolveTagNames(r.scopeTagIds),
        ].join(';'));
        const content = [header, ...csvRows].join('\n');
        const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'assignment-migration.csv';
        document.body.appendChild(a); a.click();
        document.body.removeChild(a); URL.revokeObjectURL(url);
    };

    // ── Render helpers ────────────────────────────────────────────────────────
    const resolvedScopeTagNames = (ids: string[]) =>
        ids.map(id => scopeTags.find(t => t.id === id)?.displayName || id).join(', ') || 'None';
    const actionBadgeVariant = (action: AssignmentAction) => {
        if (action === 'Add' || action === 'Replace') return 'default' as const;
        if (action === 'Remove') return 'destructive' as const;
        return 'secondary' as const;
    };

    // ── Shared pickers (inline components) ───────────────────────────────────
    const GroupPicker = ({
        search, onSearch, selectedId, selectedName, onSelect,
    }: { search: string; onSearch: (v: string) => void; selectedId: string | null; selectedName: string; onSelect: (name: string, id: string | null) => void }) => (
        <div className="space-y-1.5">
            <div className="relative">
                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
                <Input className="pl-8 h-8 text-sm" placeholder="Search groups…" value={search} onChange={e => onSearch(e.target.value)} />
            </div>
            <div className="border rounded-md max-h-40 overflow-y-auto divide-y">
                {search.trim() && (
                    <button className="w-full text-left px-3 py-1.5 hover:bg-muted text-xs"
                        onClick={() => onSelect(search.trim(), null)}>
                        Use &quot;<strong>{search.trim()}</strong>&quot; as-is
                    </button>
                )}
                {SPECIAL_TARGETS.filter(s => !search.trim() || s.toLowerCase().includes(search.toLowerCase())).map(s => (
                    <button key={s} className={`w-full text-left px-3 py-1.5 text-xs hover:bg-muted ${selectedName === s && !selectedId ? 'bg-muted font-semibold' : ''}`}
                        onClick={() => onSelect(s, null)}>{s}</button>
                ))}
                {mkGroupList(search).length === 0 && !search.trim() && (
                    <p className="text-xs text-muted-foreground px-3 py-2">Type to search groups…</p>
                )}
                {mkGroupList(search).map(g => (
                    <button key={g.id} className={`w-full text-left px-3 py-1.5 text-xs hover:bg-muted ${selectedId === g.id ? 'bg-muted font-semibold' : ''}`}
                        onClick={() => onSelect(g.displayName, g.id)}>
                        <div>{g.displayName}</div>
                        {g.membershipRule && <div className="text-[10px] text-purple-500">Dynamic group</div>}
                    </button>
                ))}
            </div>
            {selectedName && <p className="text-[11px] text-muted-foreground">Selected: <strong>{selectedName}</strong></p>}
        </div>
    );

    const FilterPicker = ({
        search, onSearch, selectedId, onSelect, onClear,
    }: { search: string; onSearch: (v: string) => void; selectedId: string | null; onSelect: (id: string, name: string) => void; onClear: () => void }) => (
        <div className="space-y-1.5">
            <div className="relative">
                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
                <Input className="pl-8 h-8 text-sm" placeholder="Search filters…" value={search} onChange={e => onSearch(e.target.value)} />
            </div>
            <div className="border rounded-md max-h-36 overflow-y-auto divide-y">
                <button className={`w-full text-left px-3 py-1.5 text-xs hover:bg-muted ${!selectedId ? 'bg-muted font-semibold' : ''}`} onClick={onClear}>
                    <span className="text-muted-foreground">— No Filter —</span>
                </button>
                {mkFilterList(search).map(f => (
                    <button key={f.id} className={`w-full text-left px-3 py-1.5 text-xs hover:bg-muted ${selectedId === f.id ? 'bg-muted font-semibold' : ''}`}
                        onClick={() => onSelect(f.id, f.displayName)}>
                        <div>{f.displayName}</div>
                        <div className="text-[10px] text-muted-foreground">{f.platform} · {f.assignmentFilterManagementType}</div>
                    </button>
                ))}
            </div>
        </div>
    );

    // Reusable slot editor for ring Include/Exclude sides
    const RingSlotEditor = ({
        slot, onChange, groupSearch, onGroupSearch, filterSearch, onFilterSearch,
    }: {
        slot: RingSlot;
        onChange: (patch: Partial<RingSlot>) => void;
        groupSearch: string; onGroupSearch: (v: string) => void;
        filterSearch: string; onFilterSearch: (v: string) => void;
    }) => (
        <div className={`space-y-4 transition-opacity ${!slot.enabled ? 'opacity-40 pointer-events-none' : ''}`}>
            <div className="space-y-1.5">
                <Label className="text-xs font-medium">Group <span className="text-red-500">*</span></Label>
                <GroupPicker
                    search={groupSearch} onSearch={onGroupSearch}
                    selectedId={slot.groupId} selectedName={slot.groupName}
                    onSelect={(name, id) => onChange({ groupName: name, groupId: id })}
                />
            </div>
            <div className="space-y-1.5">
                <Label className="text-xs font-medium">Assignment Action</Label>
                <Select value={slot.assignmentAction}
                    onValueChange={v => onChange({ assignmentAction: v as AssignmentAction })}>
                    <SelectTrigger className="h-8 text-sm"><SelectValue /></SelectTrigger>
                    <SelectContent>
                        <SelectItem value="Add">Add</SelectItem>
                        <SelectItem value="Remove">Remove</SelectItem>
                        <SelectItem value="Replace">Replace</SelectItem>
                        <SelectItem value="NoAssignment">NoAssignment</SelectItem>
                    </SelectContent>
                </Select>
            </div>
            <div className="space-y-1.5">
                <Label className="text-xs font-medium">Filter</Label>
                <FilterPicker
                    search={filterSearch} onSearch={onFilterSearch}
                    selectedId={slot.filterId}
                    onSelect={(id, name) => onChange({ filterId: id, filterName: name, filterType: slot.filterType === 'None' ? 'Include' : slot.filterType })}
                    onClear={() => onChange({ filterId: null, filterName: null, filterType: 'None' })}
                />
            </div>
            {slot.filterId && (
                <div className="space-y-1.5">
                    <Label className="text-xs font-medium">Filter Type</Label>
                    <Select value={slot.filterType}
                        onValueChange={v => onChange({ filterType: v as FilterType })}>
                        <SelectTrigger className="h-8 text-sm"><SelectValue /></SelectTrigger>
                        <SelectContent>
                            <SelectItem value="Include">Include</SelectItem>
                            <SelectItem value="Exclude">Exclude</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
            )}
            <div className="space-y-1.5">
                <Label className="text-xs font-medium">Scope Tags</Label>
                <MultiSelect options={scopeTagOptions} selected={slot.scopeTagIds}
                    onChange={ids => onChange({ scopeTagIds: ids })}
                    placeholder="Select scope tags…" />
            </div>
        </div>
    );

    // ─────────────────────────────────────────────────────────────────────────
    return (
        <div className="p-4 lg:p-8 space-y-6 w-full max-w-none">

            {/* ── Header ───────────────────────────────────────────────────── */}
            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
                <div>
                    <Button variant="ghost" size="sm" className="mb-2 -ml-2" onClick={() => router.back()}>
                        <ArrowLeft className="h-4 w-4 mr-1" /> Back
                    </Button>
                    <h1 className="text-2xl lg:text-3xl font-bold text-gray-600 dark:text-white">
                        Assignment Migration Builder
                    </h1>
                    <p className="text-gray-600 dark:text-gray-300 mt-1 text-sm">
                        Filter policies, select rows, apply bulk edits or generate ring deployment templates.
                    </p>
                </div>
                <div className="flex gap-2 flex-wrap shrink-0">
                    <Button onClick={fetchReferenceData} variant="outline" size="sm" disabled={loading}>
                        <RefreshCw className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                        {dataLoaded ? 'Refresh Data' : 'Load Reference Data'}
                    </Button>
                    {dataLoaded && (
                        <Badge variant="outline" className="h-8 px-3 flex items-center gap-1 text-green-600 border-green-400">
                            <CheckCircle2 className="h-3 w-3" />
                            {groups.length} groups · {filters.length} filters · {scopeTags.length} tags
                        </Badge>
                    )}
                    <Button onClick={exportCSV} size="sm" disabled={rows.length === 0}>
                        <Download className="h-4 w-4 mr-2" />
                        Export CSV
                    </Button>
                    <Button variant="outline" size="sm" onClick={() => router.push('/deployment/assignments')}>
                        <FileSpreadsheet className="h-4 w-4 mr-2" />
                        Go to Deployment
                    </Button>
                </div>
            </div>

            {/* ── Status badges ─────────────────────────────────────────────── */}
            {rows.length > 0 && (
                <div className="flex gap-2 flex-wrap items-center">
                    <Badge variant="secondary">{rows.length} total rows</Badge>
                    {displayedRows.length !== rows.length && <Badge variant="outline">{displayedRows.length} shown</Badge>}
                    {modifiedCount > 0 && <Badge className="bg-yellow-500 hover:bg-yellow-600">{modifiedCount} modified</Badge>}
                    {generatedCount > 0 && <Badge className="bg-purple-600 hover:bg-purple-700">{generatedCount} generated</Badge>}
                    {selectedIds.size > 0 && <Badge className="bg-blue-600 hover:bg-blue-700">{selectedIds.size} selected</Badge>}
                    {!dataLoaded && (
                        <Badge variant="outline" className="text-orange-500 border-orange-400">
                            ⚠ Load reference data to enable editing
                        </Badge>
                    )}
                </div>
            )}

            {/* ── Empty state ───────────────────────────────────────────────── */}
            {rows.length === 0 && (
                <Card className="bg-white/60 dark:bg-gray-900/30 backdrop-blur-lg border border-white/30 dark:border-white/10">
                    <CardContent className="py-16 text-center">
                        <Users className="h-16 w-16 mx-auto text-gray-400 mb-4" />
                        <h3 className="text-xl font-medium text-gray-900 dark:text-white mb-2">No assignments loaded</h3>
                        <p className="text-gray-500 dark:text-gray-400 mb-6 max-w-md mx-auto text-sm">
                            Go to the Assignments Overview page, apply your filters, then click{' '}
                            <strong>&quot;Open in Migration Builder&quot;</strong>.
                        </p>
                        <Button onClick={() => router.push('/assistant/assignments-overview')}>
                            <ArrowLeft className="h-4 w-4 mr-2" />Go to Assignments Overview
                        </Button>
                    </CardContent>
                </Card>
            )}

            {rows.length > 0 && (<>

                {/* ── Filter panel ──────────────────────────────────────────── */}
                <Card className="bg-white/60 dark:bg-gray-900/30 backdrop-blur-lg border border-white/30 dark:border-white/10">
                    <CardHeader className="pb-2 pt-3 px-4">
                        <div className="flex items-center justify-between">
                            <button className="flex items-center gap-2 text-sm font-medium hover:text-yellow-500 transition-colors"
                                onClick={() => setFilterPanelOpen(p => !p)}>
                                <Filter className="h-4 w-4" />
                                Filters
                                {activeFilterCount > 0 && (
                                    <Badge className="bg-yellow-500 text-white text-[10px] px-1.5 py-0">{activeFilterCount}</Badge>
                                )}
                                {filterPanelOpen ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
                            </button>
                            {activeFilterCount > 0 && (
                                <Button variant="ghost" size="sm" className="h-6 px-2 text-xs text-muted-foreground"
                                    onClick={() => { setScopeTagFilter([]); setResourceTypeFilter([]); setActionFilter([]); setPolicySearch(''); }}>
                                    <X className="h-3 w-3 mr-1" />Clear all
                                </Button>
                            )}
                        </div>
                    </CardHeader>
                    {filterPanelOpen && (
                        <CardContent className="pt-0 pb-4 px-4">
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mt-2">
                                <div className="space-y-1">
                                    <Label className="text-xs font-medium">Policy / Group search</Label>
                                    <div className="relative">
                                        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
                                        <Input className="pl-8 h-8 text-sm" placeholder="Search…"
                                            value={policySearch} onChange={e => setPolicySearch(e.target.value)} />
                                        {policySearch && (
                                            <button className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground"
                                                onClick={() => setPolicySearch('')}><X className="h-3 w-3" /></button>
                                        )}
                                    </div>
                                </div>
                                <div className="space-y-1">
                                    <Label className="text-xs font-medium">Scope Tags</Label>
                                    <MultiSelect options={scopeTagOptions} selected={scopeTagFilter}
                                        onChange={setScopeTagFilter} placeholder="Filter by scope tag…" />
                                </div>
                                <div className="space-y-1">
                                    <Label className="text-xs font-medium">Resource Type</Label>
                                    <MultiSelect options={resourceTypeOptions} selected={resourceTypeFilter}
                                        onChange={setResourceTypeFilter} placeholder="Filter by type…" />
                                </div>
                                <div className="space-y-1">
                                    <Label className="text-xs font-medium">Assignment Action</Label>
                                    <MultiSelect options={actionOptions} selected={actionFilter}
                                        onChange={setActionFilter} placeholder="Filter by action…" />
                                </div>
                            </div>
                        </CardContent>
                    )}
                </Card>

                {/* ── Selection action bar ──────────────────────────────────── */}
                {selectedIds.size > 0 && (
                    <Card className="border-blue-400 dark:border-blue-600 bg-blue-50/60 dark:bg-blue-900/20">
                        <CardContent className="py-3 px-4">
                            <div className="flex flex-wrap items-center gap-3">
                                <div className="flex items-center gap-2 text-sm font-medium text-blue-700 dark:text-blue-300">
                                    <Layers className="h-4 w-4" />
                                    {selectedIds.size} row{selectedIds.size > 1 ? 's' : ''} selected
                                </div>
                                <Button size="sm" variant="outline" className="h-7"
                                    onClick={() => { setRingMode(false); openTemplateDialog(); }}
                                    disabled={!dataLoaded}
                                    title={!dataLoaded ? 'Load reference data first' : 'Apply field overrides to selected rows'}>
                                    <Edit2 className="h-3.5 w-3.5 mr-1.5" />
                                    Bulk Edit
                                </Button>
                                <Button size="sm" className="h-7 bg-purple-600 hover:bg-purple-700 text-white"
                                    onClick={() => { setRingMode(true); openTemplateDialog(); }}
                                    disabled={!dataLoaded}
                                    title={!dataLoaded ? 'Load reference data first' : 'Generate Include + Exclude ring rows for selected policies'}>
                                    <Sparkles className="h-3.5 w-3.5 mr-1.5" />
                                    Ring Template
                                </Button>
                                <Button size="sm" variant="ghost" className="h-7 text-muted-foreground" onClick={clearSelection}>
                                    <X className="h-3 w-3 mr-1" />Deselect all
                                </Button>
                            </div>
                        </CardContent>
                    </Card>
                )}

                {/* ── Table ────────────────────────────────────────────────── */}
                <Card className="bg-white/60 dark:bg-gray-900/30 backdrop-blur-lg border border-white/30 dark:border-white/10 overflow-hidden">
                    <CardHeader className="pb-2 border-b">
                        <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-300">
                            Assignments ({displayedRows.length}{displayedRows.length !== rows.length ? ` of ${rows.length}` : ''})
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-0">
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm">
                                <thead>
                                    <tr className="border-b bg-muted/40">
                                        <th className="px-3 py-3 w-8">
                                            <Checkbox checked={allDisplayedSelected}
                                                data-state={someDisplayedSelected && !allDisplayedSelected ? 'indeterminate' : undefined}
                                                onCheckedChange={toggleAll} aria-label="Select all" />
                                        </th>
                                        <th className="px-3 py-3 w-5" />
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[220px]">Policy</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[140px]">Group</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-24">Direction</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-24">Action</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[130px]">Filter</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-24">Filter Type</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs min-w-[140px]">Scope Tags</th>
                                        <th className="px-3 py-3 text-left font-medium text-xs w-20">Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {displayedRows.map((row, idx) => {
                                        const isSelected = selectedIds.has(row.id);
                                        return (
                                            <tr key={row.id}
                                                className={[
                                                    'border-b transition-colors cursor-pointer',
                                                    isSelected ? 'bg-blue-50/60 dark:bg-blue-900/10' :
                                                        row.isGenerated ? 'bg-purple-50/40 dark:bg-purple-900/10' :
                                                            row.isModified ? 'bg-yellow-50/40 dark:bg-yellow-900/10' :
                                                                idx % 2 === 0 ? '' : 'bg-muted/10',
                                                    'hover:bg-muted/30',
                                                ].join(' ')}
                                                onClick={() => toggleRow(row.id)}>

                                                <td className="px-3 py-2" onClick={e => e.stopPropagation()}>
                                                    <Checkbox checked={isSelected} onCheckedChange={() => toggleRow(row.id)} />
                                                </td>

                                                {/* Status dot */}
                                                <td className="px-3 py-2">
                                                    {row.isGenerated ? (
                                                        <div className="h-2 w-2 rounded-full bg-purple-500 mx-auto" title={row.ringLabel || 'Generated'} />
                                                    ) : row.isModified ? (
                                                        <div className="h-2 w-2 rounded-full bg-yellow-500 mx-auto" title="Modified" />
                                                    ) : null}
                                                </td>

                                                {/* Policy */}
                                                <td className="px-3 py-2">
                                                    <div className="font-medium truncate max-w-70 text-xs" title={row.policyName}>
                                                        {row.policyName || <span className="text-muted-foreground italic">—</span>}
                                                    </div>
                                                    <div className="flex items-center gap-1 mt-0.5">
                                                        <span className="text-[10px] text-muted-foreground">{row.resourceType}</span>
                                                        {row.ringLabel && (
                                                            <Badge className="text-[9px] py-0 px-1 bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300 border-purple-300">
                                                                {row.ringLabel}
                                                            </Badge>
                                                        )}
                                                    </div>
                                                </td>

                                                {/* Group */}
                                                <td className="px-3 py-2">
                                                    <span className="truncate block max-w-45 text-xs" title={row.groupName}>
                                                        {row.groupName || <span className="text-muted-foreground italic">None</span>}
                                                    </span>
                                                </td>

                                                {/* Direction */}
                                                <td className="px-3 py-2">
                                                    <Badge variant={row.assignmentDirection === 'Exclude' ? 'destructive' : 'default'} className="text-[10px] py-0 px-1.5">
                                                        {row.assignmentDirection}
                                                    </Badge>
                                                </td>

                                                {/* Action */}
                                                <td className="px-3 py-2">
                                                    <Badge variant={actionBadgeVariant(row.assignmentAction)} className="text-[10px] py-0 px-1.5">
                                                        {row.assignmentAction}
                                                    </Badge>
                                                </td>

                                                {/* Filter */}
                                                <td className="px-3 py-2">
                                                    <span className="truncate block max-w-40 text-xs" title={row.filterName || ''}>
                                                        {row.filterName || <span className="text-muted-foreground text-[10px]">None</span>}
                                                    </span>
                                                </td>

                                                {/* Filter Type */}
                                                <td className="px-3 py-2">
                                                    {row.filterType !== 'None' && row.filterName ? (
                                                        <Badge variant={row.filterType === 'Include' ? 'default' : 'destructive'} className="text-[10px] py-0 px-1.5">
                                                            {row.filterType === 'Include' ? <Shield className="h-2 w-2 mr-0.5 inline" /> : <ShieldCheck className="h-2 w-2 mr-0.5 inline" />}
                                                            {row.filterType}
                                                        </Badge>
                                                    ) : (
                                                        <span className="text-muted-foreground text-[10px]">None</span>
                                                    )}
                                                </td>

                                                {/* Scope Tags */}
                                                <td className="px-3 py-2 text-[10px] text-muted-foreground max-w-40 truncate">
                                                    {row.scopeTagIds.length > 0 ? resolvedScopeTagNames(row.scopeTagIds) : 'None'}
                                                </td>

                                                {/* Actions */}
                                                <td className="px-3 py-2" onClick={e => e.stopPropagation()}>
                                                    <div className="flex gap-1">
                                                        <Button size="sm" variant="outline" className="h-6 px-2"
                                                            onClick={() => openEdit(row)} disabled={!dataLoaded}
                                                            title={dataLoaded ? 'Edit row' : 'Load reference data first'}>
                                                            <Edit2 className="h-3 w-3" />
                                                        </Button>
                                                        {row.isModified && !row.isGenerated && (
                                                            <Button size="sm" variant="ghost" className="h-6 px-2 text-muted-foreground"
                                                                onClick={() => resetRow(row.id)} title="Reset to original">
                                                                <RotateCcw className="h-3 w-3" />
                                                            </Button>
                                                        )}
                                                        {row.isGenerated && (
                                                            <Button size="sm" variant="ghost" className="h-6 px-2 text-red-500 hover:text-red-600"
                                                                onClick={() => deleteRow(row.id)} title="Remove generated row">
                                                                <X className="h-3 w-3" />
                                                            </Button>
                                                        )}
                                                    </div>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                            {displayedRows.length === 0 && (
                                <div className="py-12 text-center text-sm text-muted-foreground">
                                    No rows match the current filters.
                                </div>
                            )}
                        </div>
                    </CardContent>
                </Card>
            </>)}

            {/* ══ Template Dialog (Bulk Edit OR Ring Template) ══════════════════ */}
            <Dialog open={templateDialogOpen} onOpenChange={open => { if (!open) setTemplateDialogOpen(false); }}>
                <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle className="flex items-center gap-2">
                            {ringMode
                                ? <><Sparkles className="h-4 w-4 text-purple-500" /> Ring Template</>
                                : <><Edit2 className="h-4 w-4" /> Bulk Edit</>}
                        </DialogTitle>
                        <div className="flex items-center gap-3 pt-2">
                            <span className="text-xs text-muted-foreground">
                                {ringMode
                                    ? `Generates Include + Exclude assignment rows for ${selectedIds.size} selected polic${selectedIds.size === 1 ? 'y' : 'ies'}.`
                                    : `Overwrites fields on ${selectedIds.size} selected row${selectedIds.size === 1 ? '' : 's'}. Blank fields are not changed.`}
                            </span>
                            <div className="ml-auto flex items-center gap-2 shrink-0">
                                <Label className="text-xs">Ring Template</Label>
                                <Switch checked={ringMode} onCheckedChange={setRingMode} />
                            </div>
                        </div>
                    </DialogHeader>

                    {/* ── Ring Template mode ──────────────────────────────────── */}
                    {ringMode && (
                        <div className="space-y-4 pt-1">
                            {/* Ring name */}
                            <div className="space-y-1.5">
                                <Label className="text-sm font-medium">Template Name</Label>
                                <Input className="h-8 text-sm" placeholder="e.g. Ring 1"
                                    value={ringName} onChange={e => setRingName(e.target.value)} />
                                <p className="text-[11px] text-muted-foreground">
                                    Used as a label on generated rows (e.g. &quot;Ring 1 – Include&quot;).
                                </p>
                            </div>

                            {/* Include / Exclude tabs */}
                            <Tabs defaultValue="include" className="w-full">
                                <TabsList className="w-full">
                                    <TabsTrigger value="include" className="flex-1 gap-2">
                                        <CirclePlus className="h-3.5 w-3.5 text-green-500" />
                                        Include
                                        {ringInclude.enabled && ringInclude.groupName
                                            ? <Badge className="ml-1 text-[9px] bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 border-green-300">configured</Badge>
                                            : !ringInclude.enabled
                                                ? <Badge variant="secondary" className="ml-1 text-[9px]">disabled</Badge>
                                                : null}
                                    </TabsTrigger>
                                    <TabsTrigger value="exclude" className="flex-1 gap-2">
                                        <Shield className="h-3.5 w-3.5 text-red-500" />
                                        Exclude
                                        {ringExclude.enabled && ringExclude.groupName
                                            ? <Badge className="ml-1 text-[9px] bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300 border-red-300">configured</Badge>
                                            : !ringExclude.enabled
                                                ? <Badge variant="secondary" className="ml-1 text-[9px]">disabled</Badge>
                                                : null}
                                    </TabsTrigger>
                                </TabsList>

                                <TabsContent value="include" className="mt-4 space-y-4">
                                    <div className="flex items-center gap-2 pb-2 border-b">
                                        <Switch checked={ringInclude.enabled}
                                            onCheckedChange={v => setRingInclude(p => ({ ...p, enabled: v }))} />
                                        <Label className="text-sm">Generate Include rows</Label>
                                        <span className="text-xs text-muted-foreground ml-1">
                                            — AssignmentDirection: Include
                                        </span>
                                    </div>
                                    <RingSlotEditor
                                        slot={ringInclude}
                                        onChange={patch => setRingInclude(p => ({ ...p, ...patch }))}
                                        groupSearch={ringIncludeGroupSearch} onGroupSearch={setRingIncludeGroupSearch}
                                        filterSearch={ringIncludeFilterSearch} onFilterSearch={setRingIncludeFilterSearch}
                                    />
                                </TabsContent>

                                <TabsContent value="exclude" className="mt-4 space-y-4">
                                    <div className="flex items-center gap-2 pb-2 border-b">
                                        <Switch checked={ringExclude.enabled}
                                            onCheckedChange={v => setRingExclude(p => ({ ...p, enabled: v }))} />
                                        <Label className="text-sm">Generate Exclude rows</Label>
                                        <span className="text-xs text-muted-foreground ml-1">
                                            — AssignmentDirection: Exclude
                                        </span>
                                    </div>
                                    <RingSlotEditor
                                        slot={ringExclude}
                                        onChange={patch => setRingExclude(p => ({ ...p, ...patch }))}
                                        groupSearch={ringExcludeGroupSearch} onGroupSearch={setRingExcludeGroupSearch}
                                        filterSearch={ringExcludeFilterSearch} onFilterSearch={setRingExcludeFilterSearch}
                                    />
                                </TabsContent>
                            </Tabs>

                            {/* Preview of what will be generated */}
                            {(ringInclude.enabled || ringExclude.enabled) && (
                                <div className="rounded-md bg-muted/50 p-3 text-xs space-y-1">
                                    <p className="font-medium text-muted-foreground mb-1">Will generate per policy:</p>
                                    {ringInclude.enabled && ringInclude.groupName && (
                                        <div className="flex items-center gap-2">
                                            <Badge className="text-[9px] bg-green-100 text-green-700 border-green-300">Include</Badge>
                                            <span>{ringInclude.groupName}</span>
                                            {ringInclude.filterId && <span className="text-muted-foreground">· {ringInclude.filterName} ({ringInclude.filterType})</span>}
                                            <span className="text-muted-foreground">· {ringInclude.assignmentAction}</span>
                                        </div>
                                    )}
                                    {ringInclude.enabled && !ringInclude.groupName && (
                                        <p className="text-orange-500">⚠ Include: no group selected</p>
                                    )}
                                    {ringExclude.enabled && ringExclude.groupName && (
                                        <div className="flex items-center gap-2">
                                            <Badge className="text-[9px] bg-red-100 text-red-700 border-red-300">Exclude</Badge>
                                            <span>{ringExclude.groupName}</span>
                                            {ringExclude.filterId && <span className="text-muted-foreground">· {ringExclude.filterName} ({ringExclude.filterType})</span>}
                                            <span className="text-muted-foreground">· {ringExclude.assignmentAction}</span>
                                        </div>
                                    )}
                                    {ringExclude.enabled && !ringExclude.groupName && (
                                        <p className="text-orange-500">⚠ Exclude: no group selected</p>
                                    )}
                                </div>
                            )}

                            <div className="flex justify-between items-center pt-2 border-t">
                                <Button variant="ghost" size="sm" className="text-muted-foreground"
                                    onClick={() => {
                                        setRingInclude({ ...EMPTY_RING_SLOT });
                                        setRingExclude({ ...EMPTY_RING_SLOT });
                                        setRingName('Ring 1');
                                    }}>
                                    <RotateCcw className="h-3.5 w-3.5 mr-1" />Reset
                                </Button>
                                <div className="flex gap-2">
                                    <Button variant="outline" size="sm" onClick={() => setTemplateDialogOpen(false)}>Cancel</Button>
                                    <Button size="sm" className="bg-purple-600 hover:bg-purple-700 text-white"
                                        disabled={
                                            (!ringInclude.enabled && !ringExclude.enabled) ||
                                            (ringInclude.enabled && !ringInclude.groupName) ||
                                            (ringExclude.enabled && !ringExclude.groupName)
                                        }
                                        onClick={applyRingTemplate}>
                                        <Sparkles className="h-3.5 w-3.5 mr-1.5" />
                                        Generate rows for {selectedIds.size} polic{selectedIds.size === 1 ? 'y' : 'ies'}
                                    </Button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* ── Bulk Edit mode ───────────────────────────────────────── */}
                    {!ringMode && (
                        <div className="space-y-5 pt-1">
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Group <span className="text-muted-foreground font-normal text-xs">(optional)</span></Label>
                                <GroupPicker
                                    search={bulkGroupSearch} onSearch={setBulkGroupSearch}
                                    selectedId={bulk.groupId} selectedName={bulk.groupName}
                                    onSelect={(name, id) => setBulk(p => ({ ...p, groupName: name, groupId: id }))}
                                />
                                {bulk.groupName && (
                                    <Button variant="ghost" size="sm" className="h-6 text-xs text-muted-foreground px-2"
                                        onClick={() => { setBulk(p => ({ ...p, groupName: '', groupId: null })); setBulkGroupSearch(''); }}>
                                        <X className="h-3 w-3 mr-1" />Clear group
                                    </Button>
                                )}
                            </div>
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Assignment Action <span className="text-muted-foreground font-normal text-xs">(optional)</span></Label>
                                <Select value={bulk.assignmentAction}
                                    onValueChange={v => setBulk(p => ({ ...p, assignmentAction: v as AssignmentAction | '__keep__' }))}>
                                    <SelectTrigger className="h-8 text-sm"><SelectValue placeholder="— keep existing —" /></SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="__keep__">— keep existing —</SelectItem>
                                        <SelectItem value="Add">Add</SelectItem>
                                        <SelectItem value="Remove">Remove</SelectItem>
                                        <SelectItem value="Replace">Replace</SelectItem>
                                        <SelectItem value="NoAssignment">NoAssignment</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Filter <span className="text-muted-foreground font-normal text-xs">(optional)</span></Label>
                                <FilterPicker
                                    search={bulkFilterSearch} onSearch={setBulkFilterSearch}
                                    selectedId={bulk.filterId}
                                    onSelect={(id, name) => setBulk(p => ({ ...p, filterId: id, filterName: name, filterType: p.filterType === 'None' ? 'Include' : p.filterType }))}
                                    onClear={() => setBulk(p => ({ ...p, filterId: null, filterName: null, filterType: 'None' }))}
                                />
                            </div>
                            {bulk.filterId && (
                                <div className="space-y-2">
                                    <Label className="text-sm font-medium">Filter Type</Label>
                                    <Select value={bulk.filterType}
                                        onValueChange={v => setBulk(p => ({ ...p, filterType: v as FilterType }))}>
                                        <SelectTrigger className="h-8 text-sm"><SelectValue /></SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="Include">Include</SelectItem>
                                            <SelectItem value="Exclude">Exclude</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                            )}
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Scope Tags <span className="text-muted-foreground font-normal text-xs">(optional — replaces existing)</span></Label>
                                <MultiSelect options={scopeTagOptions} selected={bulk.scopeTagIds}
                                    onChange={ids => setBulk(p => ({ ...p, scopeTagIds: ids }))}
                                    placeholder="Select scope tags…" />
                            </div>
                            <div className="flex justify-between items-center pt-2 border-t">
                                <Button variant="ghost" size="sm" className="text-muted-foreground"
                                    onClick={() => setBulk({ groupName: '', groupId: null, assignmentAction: '__keep__', filterId: null, filterName: null, filterType: 'None', scopeTagIds: [] })}>
                                    <RotateCcw className="h-3.5 w-3.5 mr-1" />Clear
                                </Button>
                                <div className="flex gap-2">
                                    <Button variant="outline" size="sm" onClick={() => setTemplateDialogOpen(false)}>Cancel</Button>
                                    <Button size="sm" onClick={applyBulkTemplate}>
                                        Apply to {selectedIds.size} row{selectedIds.size === 1 ? '' : 's'}
                                    </Button>
                                </div>
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>

            {/* ── Single-row Edit Dialog ────────────────────────────────────── */}
            <Dialog open={editDialogOpen} onOpenChange={open => { if (!open) setEditDialogOpen(false); }}>
                <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                        <DialogTitle className="text-base">Edit Assignment</DialogTitle>
                        {editingRow && <p className="text-xs text-muted-foreground truncate pt-1">{editingRow.policyName}</p>}
                    </DialogHeader>
                    {editingRow && (
                        <div className="space-y-5 pt-1">
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Group (Target Name)</Label>
                                <GroupPicker
                                    search={groupSearch} onSearch={setGroupSearch}
                                    selectedId={editingRow.groupId} selectedName={editingRow.groupName}
                                    onSelect={(name, id) => setEditingRow(p => p ? { ...p, groupName: name, groupId: id } : null)}
                                />
                            </div>
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Assignment Action</Label>
                                <Select value={editingRow.assignmentAction}
                                    onValueChange={v => setEditingRow(p => p ? { ...p, assignmentAction: v as AssignmentAction } : null)}>
                                    <SelectTrigger className="h-8 text-sm"><SelectValue /></SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="Add">Add</SelectItem>
                                        <SelectItem value="Remove">Remove</SelectItem>
                                        <SelectItem value="Replace">Replace</SelectItem>
                                        <SelectItem value="NoAssignment">NoAssignment</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Filter</Label>
                                <FilterPicker
                                    search={filterSearch} onSearch={setFilterSearch}
                                    selectedId={editingRow.filterId}
                                    onSelect={(id, name) => setEditingRow(p => p ? { ...p, filterId: id, filterName: name, filterType: p.filterType === 'None' ? 'Include' : p.filterType } : null)}
                                    onClear={() => setEditingRow(p => p ? { ...p, filterId: null, filterName: null, filterType: 'None' } : null)}
                                />
                            </div>
                            {editingRow.filterId && (
                                <div className="space-y-2">
                                    <Label className="text-sm font-medium">Filter Type</Label>
                                    <Select value={editingRow.filterType}
                                        onValueChange={v => setEditingRow(p => p ? { ...p, filterType: v as FilterType } : null)}>
                                        <SelectTrigger className="h-8 text-sm"><SelectValue /></SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="Include">Include</SelectItem>
                                            <SelectItem value="Exclude">Exclude</SelectItem>
                                            <SelectItem value="None">None</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                            )}
                            <div className="space-y-2">
                                <Label className="text-sm font-medium">Scope Tags</Label>
                                <MultiSelect options={scopeTagOptions} selected={editingRow.scopeTagIds}
                                    onChange={ids => setEditingRow(p => p ? { ...p, scopeTagIds: ids } : null)}
                                    placeholder="Select scope tags…" />
                            </div>
                            <div className="flex justify-between items-center pt-2 border-t">
                                <Button variant="ghost" size="sm" className="text-muted-foreground"
                                    onClick={() => setEditingRow(p => p ? { ...p, ...p.original } : null)}>
                                    <RotateCcw className="h-3.5 w-3.5 mr-1" />Reset to Original
                                </Button>
                                <div className="flex gap-2">
                                    <Button variant="outline" size="sm" onClick={() => setEditDialogOpen(false)}>Cancel</Button>
                                    <Button size="sm" onClick={saveEdit}>Save Changes</Button>
                                </div>
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>

        </div>
    );
}

